import*as THREE from'three';import{Button}from'../../core/index.js';import{FACE}from'../../modeling/parts.js';import{spec}from'./dimensions.js';
/** Bends the actual integral CAD tongue; no detached or duplicated visible cap. */
export class NativeButton extends Button{
 constructor(shell,side=false){const hit=new THREE.Mesh(new THREE.PlaneGeometry(side?6.0:10.6,side?3.8:5.8),new THREE.MeshBasicMaterial({transparent:true,opacity:0,depthWrite:false}));hit.name='C6L '+(side?'side reset':'front user')+' native tongue input target';hit.position.z=.025;const s=side?spec.reset:spec.user;
  super({id:side?'reset':'user',label:side?'Side reset / boot input intent':'Front user input intent E0.P0',mesh:hit,position:s.position,...(side?{quaternion:FACE.left}:{}),axis:[0,0,-1],travel:s.travelMm,longPressMs:side?3000:800,meta:{role:'visual-control',visualMotion:'native-flexure',surfaceFace:side?'left':'front',source:side?'S1 common reset/boot key':'S2 SYS_KEY1 E0.P0',travelSource:'Local visual travel estimate; native U-cut and retained hinge preserved, no rated switch travel or material physics.',scope:'Physical press/release/cancel and external input intent only; no automatic boot,reset,firmware,green/red transition,RGB,OLED,LoRa or power behavior.'}});
  this.object3d.add(hit);this.shell=shell;this.side=side;this.restPositions=shell.geometry.attributes.position.array.slice();this.restNormals=shell.geometry.attributes.normal.array.slice();this.weights=new Float32Array(this.restPositions.length/3);this.slopes=new Float32Array(this.weights.length);this.lastDepth=0;
  for(let i=0;i<this.weights.length;i++){const x=this.restPositions[i*3],y=this.restPositions[i*3+1],z=this.restPositions[i*3+2];let eligible,t;
   if(side){eligible=x<=-10.249&&y>=-9.894&&y<=-3.106&&z>=s.hingeZ&&z<=s.freeZ+.001;t=(z-s.hingeZ)/(s.freeZ-s.hingeZ);}
   else{eligible=Math.abs(x)<=6.201&&y>=s.hingeY&&y<=s.freeY+.001&&z>=1.299&&(Math.abs(x)<=4.801||y<=-4||((Math.abs(x)-4.8)**2+(y+4)**2)<=1.401**2);t=(y-s.hingeY)/(s.freeY-s.hingeY);}
   if(eligible){t=THREE.MathUtils.clamp(t,0,1);this.weights[i]=t*t*(3-2*t);this.slopes[i]=6*t*(1-t)/(side?s.freeZ-s.hingeZ:s.freeY-s.hingeY);}
  }this.meta.deformedNativeVertices=this.weights.filter(v=>v>0).length;
 }
 update(dt){const changed=super.update(dt),depth=this.getActuationState().depthMm;if(depth===this.lastDepth)return changed;const p=this.shell.geometry.attributes.position,n=this.shell.geometry.attributes.normal;for(let i=0;i<this.weights.length;i++){if(!this.weights[i])continue;const o=i*3,x=this.restPositions[o],y=this.restPositions[o+1],z=this.restPositions[o+2];p.setXYZ(i,x+(this.side?depth*this.weights[i]:0),y,z-(this.side?0:depth*this.weights[i]));let nx=this.restNormals[o],ny=this.restNormals[o+1],nz=this.restNormals[o+2];if(depth){if(this.side)nz-=depth*this.slopes[i]*nx;else ny+=depth*this.slopes[i]*nz;const l=Math.hypot(nx,ny,nz);nx/=l;ny/=l;nz/=l;}n.setXYZ(i,nx,ny,nz);}p.needsUpdate=true;n.needsUpdate=true;this.shell.geometry.computeBoundingBox();this.shell.geometry.computeBoundingSphere();for(const f of this.followers??[])f.mesh.position[f.axis]=f.rest+depth*f.scale;this.lastDepth=depth;return true;}
 dispose(){super.dispose();this.shell=null;this.restPositions=null;this.restNormals=null;this.weights=null;this.slopes=null;}
}
